css:
.rtm-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #f8fafc 0%, #eef2f7 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    color: #0f172a;
}
.rtm-sim-header {
    background: linear-gradient(135deg, #0f172a 0%, #1e293b 50%, #0d9488 140%);
    color: #f1f5f9;
    border-radius: 14px;
    padding: 28px 32px;
    margin-bottom: 22px;
    box-shadow: 0 10px 30px rgba(15,23,42,0.18);
    position: relative;
    overflow: hidden;
}
.rtm-sim-header::after {
    content: '';
    position: absolute;
    right: -40px;
    top: -40px;
    width: 200px;
    height: 200px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba(13,148,136,0.35), transparent 70%);
}
.rtm-sim-header-brand {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 10px;
}
.rtm-sim-header-badge {
    background: #f59e0b;
    color: #1a2744;
    font-weight: 700;
    letter-spacing: 0.12em;
    padding: 4px 10px;
    border-radius: 4px;
    font-size: 0.75rem;
}
.rtm-sim-header-sector {
    color: #94a3b8;
    font-size: 0.8rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}
.rtm-sim-header h1 {
    margin: 0 0 6px 0;
    font-size: 1.75rem;
    font-weight: 700;
    letter-spacing: -0.01em;
}
.rtm-sim-header-sub {
    margin: 0;
    color: #cbd5e1;
    font-size: 0.95rem;
    max-width: 720px;
}
.rtm-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-left: 5px solid #0d9488;
    border-radius: 10px;
    padding: 14px 20px;
    margin-bottom: 20px;
    font-weight: 600;
}
.rtm-sim-period-counter {
    color: #475569;
    font-size: 0.95rem;
}
.rtm-sim-period-counter span {
    margin: 0 3px;
}
.rtm-sim-period-counter span:nth-child(2),
.rtm-sim-period-counter span:nth-child(4) {
    color: #0d9488;
    font-weight: 800;
    font-size: 1.1rem;
}
.rtm-sim-period-title {
    color: #0f172a;
    font-size: 1.05rem;
    font-weight: 700;
}
.rtm-sim-briefing {
    display: flex;
    gap: 16px;
    background: #fffbeb;
    border: 1px solid #fcd34d;
    border-left: 5px solid #f59e0b;
    padding: 18px 22px;
    border-radius: 10px;
    margin-bottom: 22px;
}
.rtm-sim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}
.rtm-sim-briefing-body h3 {
    margin: 0 0 8px 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #78350f;
}
.rtm-sim-briefing-body p {
    margin: 0;
    color: #334155;
    font-size: 0.92rem;
    line-height: 1.55;
}
.rtm-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 14px;
    margin-bottom: 24px;
}
.rtm-sim-kpi-card {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 18px 16px 18px;
    border-top: 4px solid #94a3b8;
    box-shadow: 0 4px 12px rgba(15,23,42,0.06);
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.rtm-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 22px rgba(15,23,42,0.1);
}
.rtm-sim-kpi-budget { border-top-color: #0d9488; }
.rtm-sim-kpi-response { border-top-color: #3b82f6; }
.rtm-sim-kpi-burnout { border-top-color: #dc2626; }
.rtm-sim-kpi-satisfaction { border-top-color: #8b5cf6; }
.rtm-sim-kpi-men { border-top-color: #f59e0b; }
.rtm-sim-kpi-stress { border-top-color: #ef4444; }
.rtm-sim-kpi-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: #64748b;
    margin-bottom: 8px;
    font-weight: 600;
}
.rtm-sim-kpi-value {
    font-size: 1.75rem;
    font-weight: 800;
    color: #0f172a;
    line-height: 1.1;
    margin-bottom: 6px;
}
.rtm-sim-kpi-hint {
    font-size: 0.72rem;
    color: #94a3b8;
}
.rtm-sim-controls {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 24px 26px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(15,23,42,0.05);
}
.rtm-sim-controls h3 {
    margin: 0 0 18px 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #0f172a;
    padding-bottom: 10px;
    border-bottom: 2px solid #e2e8f0;
}
.rtm-sim-control-section {
    margin-bottom: 22px;
    padding: 16px 18px;
    background: #f8fafc;
    border-radius: 8px;
}
.rtm-sim-control-section h4 {
    margin: 0 0 14px 0;
    font-size: 0.9rem;
    font-weight: 700;
    color: #0d9488;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}
.rtm-sim-control-row {
    margin-bottom: 12px;
}
.rtm-sim-control-row label {
    display: block;
    font-size: 0.86rem;
    font-weight: 600;
    color: #334155;
    margin-bottom: 6px;
}
.rtm-sim-control-row select,
.rtm-sim-invest-item input[type="number"] {
    width: 100%;
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #0f172a;
    padding: 9px 12px;
    border-radius: 6px;
    font-size: 0.92rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.rtm-sim-control-row select:focus,
.rtm-sim-invest-item input[type="number"]:focus {
    outline: none;
    border-color: #0d9488;
    box-shadow: 0 0 0 3px rgba(13,148,136,0.15);
}
.rtm-sim-control-row select option {
    background: #ffffff;
    color: #0f172a;
}
.rtm-sim-budget-note {
    font-size: 0.82rem;
    color: #64748b;
    margin: 0 0 14px 0;
}
.rtm-sim-invest-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
    gap: 12px;
}
.rtm-sim-invest-item label {
    display: block;
    font-size: 0.82rem;
    font-weight: 600;
    color: #334155;
    margin-bottom: 6px;
}
.rtm-sim-budget-total {
    margin-top: 14px;
    padding: 10px 14px;
    background: #ecfdf5;
    border-left: 4px solid #0d9488;
    border-radius: 4px;
    font-size: 0.9rem;
    font-weight: 600;
    color: #0f172a;
}
.rtm-sim-budget-total.over {
    background: #fef2f2;
    border-left-color: #dc2626;
    color: #991b1b;
}
.rtm-sim-action-row {
    display: flex;
    gap: 10px;
    justify-content: flex-end;
    margin-top: 8px;
}
.rtm-sim-action-row .btn-primary {
    background: #0d9488;
    border-color: #0d9488;
    font-weight: 600;
    padding: 10px 22px;
    border-radius: 6px;
}
.rtm-sim-action-row .btn-primary:hover {
    background: #0f766e;
    border-color: #0f766e;
}
.rtm-sim-action-row .btn-outline-secondary {
    border-color: #cbd5e1;
    color: #64748b;
    border-radius: 6px;
}
.rtm-sim-history {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 20px 24px;
    margin-bottom: 24px;
    box-shadow: 0 4px 14px rgba(15,23,42,0.05);
}
.rtm-sim-history h3 {
    margin: 0 0 14px 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #0f172a;
}
.rtm-sim-history table {
    width: 100%;
    font-size: 0.88rem;
}
.rtm-sim-history table thead th {
    background: #0f172a;
    color: #f1f5f9;
    font-weight: 600;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    padding: 10px 12px;
    border: none;
}
.rtm-sim-history table tbody td {
    padding: 10px 12px;
    color: #334155;
    border-bottom: 1px solid #e2e8f0;
}
.rtm-sim-history table tbody tr:hover td {
    background: #f1f5f9;
}
.rtm-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(380px, 1fr));
    gap: 18px;
    margin-bottom: 20px;
}
.rtm-sim-chart-box {
    background: #ffffff;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 18px;
    box-shadow: 0 4px 14px rgba(15,23,42,0.05);
    height: 320px;
}
@media (max-width: 768px) {
    .rtm-sim-container { padding: 16px; }
    .rtm-sim-header { padding: 20px; }
    .rtm-sim-header h1 { font-size: 1.35rem; }
    .rtm-sim-period-bar { flex-direction: column; align-items: flex-start; gap: 6px; }
    .rtm-sim-kpi-value { font-size: 1.45rem; }
    .rtm-sim-invest-grid { grid-template-columns: 1fr; }
    .rtm-sim-action-row { flex-direction: column; }
    .rtm-sim-action-row button { width: 100%; }
}

