            decisions.investWellbeing = this._num('investWellbeing');
            decisions.investConnectivity = this._num('investConnectivity');

            var total = decisions.investTools + decisions.investTraining +
                        decisions.investWellbeing + decisions.investConnectivity;

            if (total > this.BUDGET_CAP) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('err_over_budget'), 'warning'
                );
                return false;
            }
            if (total <= 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('err_no_invest'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;

            var measurementMap = {
                'outputs': 1.30,
                'inputs_light': 1.00,
                'surveillance': 0.70
            };
            var coreMap = {
                'none': 1.00,
                '4hours': 0.78,
                '6hours': 0.88,
                '8hours': 0.98
            };
            var measMul = measurementMap[d.measurementPhilosophy] || 1.0;
            var coreMul = coreMap[d.coreHoursPolicy] || 1.0;
            var discBonus = (d.disconnectionLaw === 'yes') ? 1 : 0;

            var toolsEff = d.investTools * 0.012;
            var trainEff = d.investTraining * 0.010;
            var wellEff = d.investWellbeing * 0.011;
            var connEff = d.investConnectivity * 0.014;

            var newResponseTime = ds.responseTime * coreMul;
            newResponseTime -= toolsEff * 1.8;
            newResponseTime -= trainEff * 1.4;
            newResponseTime -= connEff * 0.9;
            newResponseTime = newResponseTime / measMul;
            newResponseTime = Math.max(2.5, newResponseTime);

            var newBurnout = ds.burnoutPct;
            newBurnout -= wellEff * 6.5;
            newBurnout -= trainEff * 2.5;
            newBurnout -= discBonus * 7;
            if (d.measurementPhilosophy === 'surveillance') newBurnout += 12;
            if (d.coreHoursPolicy === '8hours') newBurnout += 4;
            if (d.coreHoursPolicy === '4hours') newBurnout -= 3;
            newBurnout = Math.max(6, Math.min(85, newBurnout));

            var responseGain = Math.max(0, (ds.responseTime - newResponseTime));
            var newSatisfaction = ds.satisfaction + (responseGain * 1.8) + (connEff * 2.0);
            if (d.measurementPhilosophy === 'surveillance') newSatisfaction -= 3;
            newSatisfaction = Math.max(35, Math.min(98, newSatisfaction));

            var newStress = ds.stressCost;
            newStress -= wellEff * 22;
            newStress -= discBonus * 18;
            if (d.measurementPhilosophy === 'surveillance') newStress += 45;
            if (d.coreHoursPolicy === '8hours') newStress += 15;
            newStress = Math.max(90, Math.min(420, newStress));

            var newMenCompliance = 60 + (24 - newResponseTime) * 2.8 + connEff * 3.2 + (newSatisfaction - 66) * 0.4;
            newMenCompliance = Math.max(40, Math.min(99, newMenCompliance));

            var newNightActivity = ds.nightActivityPct * coreMul - (discBonus * 5) - (trainEff * 3);
            newNightActivity = Math.max(4, Math.min(60, newNightActivity));

            var investedThisRound = d.investTools + d.investTraining + d.investWellbeing + d.investConnectivity;
            ds.totalInvested += investedThisRound;
            ds.budgetUsed = investedThisRound;

            ds.responseTime = Math.round(newResponseTime * 10) / 10;
            ds.burnoutPct = Math.round(newBurnout);
            ds.satisfaction = Math.round(newSatisfaction);
            ds.menCompliance = Math.round(newMenCompliance);
            ds.stressCost = Math.round(newStress);
            ds.nightActivityPct = Math.round(newNightActivity);

            ds.responseTimeHistory.push(ds.responseTime);
            ds.menComplianceHistory.push(ds.menCompliance);
            ds.satisfactionHistory.push(ds.satisfaction);
            ds.burnoutHistory.push(ds.burnoutPct);

            var matriculasAtRisk = 85000;
            var rescueFactor = Math.max(0, (ds.menCompliance - 65) / 30);
            var rescuedRevenue = matriculasAtRisk * Math.min(1, rescueFactor);
            var stressSavings = Math.max(0, 340 - ds.stressCost);
            var quarterlyBenefit = (rescuedRevenue / 4) + stressSavings;
            var roiRatio = ds.totalInvested > 0 ? (quarterlyBenefit / ds.totalInvested) : 0;

            ds.profitHistory.push(Math.round(quarterlyBenefit));
            ds.salesHistory.push(ds.menCompliance);

            // Platform score: same 0-8 point score getPerformanceSummary sums (2/1/0 points each for
            // MEN compliance, burnout, satisfaction, response time against its own cutoffs), scaled to
            // 0-100 so its 7/5/3 tier cutoffs land at about 88/63/38 on the running score.
            var perfPoints = 0;
            if (ds.menCompliance >= 90) perfPoints += 2; else if (ds.menCompliance >= 80) perfPoints += 1;
            if (ds.burnoutPct <= 20) perfPoints += 2; else if (ds.burnoutPct <= 30) perfPoints += 1;
            if (ds.satisfaction >= 85) perfPoints += 2; else if (ds.satisfaction >= 75) perfPoints += 1;
            if (ds.responseTime <= 4) perfPoints += 2; else if (ds.responseTime <= 8) perfPoints += 1;
            var overallScore = Math.max(0, Math.min(100, Math.round(perfPoints / 8 * 100)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var self = this;
            // v1.1.0 FIX: capture nextPeriod BEFORE the async. The host increments
            // state.currentPeriod synchronously after calculateResults() returns, so reading it
            // inside the timer was two quarters ahead — quarters 2-3 showed the wrong briefing.
            var nextPeriod = (state.currentPeriod || 1) + 1;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
                self._refreshBudgetDisplay();
            }, 400);

            return {
                period: state.currentPeriod,
                responseTime: ds.responseTime,
                burnoutPct: ds.burnoutPct,
                satisfaction: ds.satisfaction,
                menCompliance: ds.menCompliance,
                stressCost: ds.stressCost,
                investedThisRound: investedThisRound,
                totalInvested: ds.totalInvested,
                quarterlyBenefit: Math.round(quarterlyBenefit),
                roiRatio: Math.round(roiRatio * 100) / 100
            };
        }

        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var tFn = window.mySimulation && window.mySimulation.t ?
                window.mySimulation.t.bind(window.mySimulation) :
                function(k) { return k; };

            var titleEl = document.getElementById('briefingTitle');
            var textEl = document.getElementById('briefingText');
            var roundTitleEl = document.getElementById('roundTitle');

            if (titleEl) titleEl.textContent = tFn(round.titleKey);
            if (textEl) textEl.innerHTML = tFn(round.briefKey);
            if (roundTitleEl) roundTitleEl.textContent = tFn(round.titleKey);
        }

